-- category_crop_mapping：把 2026-08-31 只存在於 DEV 的 1152 筆人工策展映射
-- 補成 migration，讓 PROD 取得同一份分類→行情大類對應。
--
-- 為什麼需要這支：
--   20260830034310_bootstrap_category_crop_mapping_exact_matches.sql 只帶了
--   279 筆寫死的 VALUES。DEV 另有 1152 筆是 2026-08-31 透過
--   POST /admin/pricebook/category-mapping 寫入的（updated_by=900000001，
--   dev 假造 admin token 的佔位 accountId），從未進入任何 migration，因此
--   PROD 永遠拿不到。實測後果：PROD 的
--   GET /app/sellers/pricebook/category-price-rollup?category_id=117（甘藍 L2）
--   回 status="unavailable"、sourceGroupCount=0，賣家中心市場行情頁對這批
--   分類全部顯示「目前沒有可用的彙整行情資料」；同一支在 DEV 回 ready/28.7416。
--   缺口約佔分類總數的 1152/1431。
--
-- 為什麼是寫死 VALUES 而不是靠名稱比對重算：
--   #2786 明訂「名稱比對只可作後台候選，不可自動採信」。這裡直接搬既有的
--   人工策展結果，不在 migration 內重跑任何比對邏輯，避免 PROD 與 DEV 因
--   catalog 內容差異而算出不同映射。
--
-- 安全性：
--   1. INSERT ... SELECT 帶 EXISTS 守衛——group_code 在該環境的 crop_group
--      不存在時整列跳過，不會建立指向不存在大類的映射（fail closed）。
--   2. ON CONFLICT (category_id) DO NOTHING——已存在的列一律不覆蓋，保護
--      任何環境自行策展過的內容；本 migration 可重複套用。
--   3. updated_by 寫 0（migration 套用），與 279 筆 bootstrap 一致；不沿用
--      900000001，那是 dev 假 token 的佔位值，不該出現在 PROD 稽核欄位。
--
-- 套用後仍須人工確認（見 PR 說明）：PROD 的 product category 樹是否與 DEV
-- 共用同一組 category_id。若不同，這些 id 會對到別的分類——此為資料正確性
-- 風險，migration 本身無法跨 DB 驗證（category 樹在 hawkr_product）。

INSERT INTO category_crop_mapping
    (category_id, status, group_code, mapping_version, source_note, updated_by)
SELECT v.category_id, 'resolved', v.group_code, 'pricebook-category-v1', v.source_note, 0
